public @Nullable RelNode convert(RelNode rel) {
    final LogicalTableFunctionScan functionScan = (LogicalTableFunctionScan) rel;
    final RelTraitSet traitSet =
            rel.getTraitSet().replace(FlinkConventions.LOGICAL()).simplify();
    final List<RelNode> newInputs =
            functionScan.getInputs().stream()
                    .map(input -> RelOptRule.convert(input, FlinkConventions.LOGICAL()))
                    .collect(Collectors.toList());
    final RexCall rexCall = (RexCall) functionScan.getCall();
    return new FlinkLogicalTableFunctionScan(
            functionScan.getCluster(),
            traitSet,
            newInputs,
            rexCall,
            functionScan.getElementType(),
            functionScan.getRowType(),
            functionScan.getColumnMappings());
}

private FlinkLogicalTableFunctionScan createNewScan(
        FlinkLogicalTableFunctionScan scan, ScalarFunctionSplitter splitter) {
    RexCall rightRexCall = (RexCall) scan.getCall();
    // extract Java funcs from Remote TableFunction or Remote funcs from Java TableFunction.
    List<RexNode> rightCalcProjects =
            rightRexCall.getOperands().stream()
                    .map(x -> x.accept(splitter))
                    .collect(Collectors.toList());

    RexCall newRightRexCall = rightRexCall.clone(rightRexCall.getType(), rightCalcProjects);
    return new FlinkLogicalTableFunctionScan(
            scan.getCluster(),
            scan.getTraitSet(),
            scan.getInputs(),
            newRightRexCall,
            scan.getElementType(),
            scan.getRowType(),
            scan.getColumnMappings());
}

