            sb.append(Cookie.escape(key));
            sb.append("=");
            sb.append(Cookie.escape(value.toString()));
            isEndOfPair = true;
        }
    }
    return sb.toString();
}

private static boolean isNumericChar(char c) {
    return (c <= '9' && c >= '0');
}

public static String toString(JSONObject jo) throws JSONException {
    boolean             isEndOfPair = false;
    final StringBuilder sb = new StringBuilder();
    // Don't use the new entrySet API to maintain Android support
    for (final String key : jo.keySet()) {
        final Object value = jo.opt(key);
        if (!JSONObject.NULL.equals(value)) {
            if (isEndOfPair) {
                sb.append(';');
            }
            sb.append(Cookie.escape(key));
            sb.append("=");
            sb.append(Cookie.escape(value.toString()));
            isEndOfPair = true;
        }
    }
    return sb.toString();
}

public XMLParserConfiguration withCloseEmptyTag(boolean closeEmptyTag){
    XMLParserConfiguration clonedConfiguration = this.clone();
    clonedConfiguration.closeEmptyTag = closeEmptyTag;
    return clonedConfiguration;
}

private JSONMLParserConfiguration(final boolean keepStrings, final int maxNestingDepth) {
    this.keepStrings = keepStrings;
    this.maxNestingDepth = maxNestingDepth;
}
